# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _stud(last, first):
    return Student("id-" + last, last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        studs = [
            _stud("Halloway", "Juno"),
            _stud("Dunmere", "Piet"),
            _stud("Abel", "Zoe"),
        ]
        self.assertEqual(
            seating_rows(studs, 2),
            [
                "Row 1: Abel, Zoe | Dunmere, Piet",
                "Row 2: Halloway, Juno",
            ],
        )

    def test_bad_seat_count(self):
        studs = [_stud("Abel", "Zoe")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(studs, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)

if __name__ == "__main__":
    unittest.main()
